.portal-wrap { position: relative; width: 100%; height: 300vh; }
#portal-canvas { position: fixed; top: 0; left: 0; width: 100%; height: 100vh; z-index: 1; pointer-events: none; }
.portal-text-layer {
  position: fixed; top: 0; left: 0; width: 100%; height: 100vh;
  display: flex; align-items: center; justify-content: center; z-index: 2; pointer-events: none;
}
.portal-msg {
  position: absolute; color: #fff; font-size: 35px; font-weight: 900; text-align: center;
  opacity: 0; transition: opacity 0.3s; text-shadow: 0 0 20px #ff00ff;
}

jsCode:
const pc = document.getElementById('container');
pc.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#0a001a;position:relative;';

pc.innerHTML = `
  <div class="portal-wrap">
    <canvas id="portal-canvas"></canvas>
    <div class="portal-text-layer">
      <div id="pMsg1" class="portal-msg" style="font-size:20px; top:10%;">Enter the Portal ↓</div>
      <div id="pMsg2" class="portal-msg" style="color:#ff007f;">INFINITY</div>
      <div id="pMsg3" class="portal-msg" style="font-size:55px; color:#00ffcc;">PRO</div>
    </div>
  </div>
`;

const pCvs = document.getElementById('portal-canvas');
const pCtx = pCvs.getContext('2d');
let pW, pH;
let pParticles = [], pShapes = [];
const prCount = 900;

function getPortalPts(txt, size) {
  const tc = document.createElement('canvas');
  tc.width = pW; tc.height = pH;
  const tctx = tc.getContext('2d');
  tctx.fillStyle = 'white'; tctx.font = `900 ${size}px sans-serif`;
  tctx.textAlign = 'center'; tctx.textBaseline = 'middle';
  tctx.fillText(txt, pW/2, pH/2);
  const data = tctx.getImageData(0,0,pW,pH).data;
  let pts = [];
  for(let y=0; y<pH; y+=7){
    for(let x=0; x<pW; x+=7){
      if(data[(y*pW+x)*4+3] > 128) pts.push({x:x, y:y});
    }
  }
  return pts.length ? pts : [{x: pW/2, y: pH/2}];
}

function initPortal() {
  pW = pCvs.width = window.innerWidth;
  pH = pCvs.height = window.innerHeight;

  let s1 = []; 
  for(let i=0; i<prCount; i++) {
    let t = (i / prCount) * Math.PI * 2;
    let scale = Math.min(pW, pH) * 0.3;
    let x = (scale * Math.cos(t)) / (1 + Math.sin(t)*Math.sin(t));
    let y = (scale * Math.sin(t) * Math.cos(t)) / (1 + Math.sin(t)*Math.sin(t));
    s1.push({x: pW/2 + x, y: pH/2 + y});
  }

  let s2 = getPortalPts('INFINITY', Math.min(pW/4, 50));
  let s3 = getPortalPts('PRO', Math.min(pW/3, 80));

  pShapes = [s1, s2, s3, s3];
  pParticles = [];
  for(let i=0; i<prCount; i++){
    pParticles.push({ x: pW/2, y: pH/2, c: `hsl(${280 + Math.random()*80}, 100%, 60%)` }); 
  }
}
initPortal(); window.addEventListener('resize', initPortal);

let pProg = 0;
pc.addEventListener('scroll', () => {
  pProg = pc.scrollTop / (pc.scrollHeight - pc.clientHeight);
  document.getElementById('pMsg1').style.opacity = (pProg < 0.1) ? 1 : 0;
  document.getElementById('pMsg2').style.opacity = (pProg > 0.35 && pProg < 0.6) ? 1 : 0;
  document.getElementById('pMsg3').style.opacity = (pProg > 0.8) ? 1 : 0;
});

// ERROR FIXED HERE: lerp ફંક્શન ઉમેર્યું છે
function lerp(a, b, t) { return a + (b - a) * t; }

function drawPortal() {
  pCtx.fillStyle = 'rgba(10, 0, 26, 0.2)'; 
  pCtx.fillRect(0,0,pW,pH);

  let stage = pProg * 3;
  let cStage = Math.floor(stage);
  let nStage = Math.min(cStage + 1, 3);
  let tProg = stage - cStage;

  let pts1 = pShapes[cStage], pts2 = pShapes[nStage];

  for(let i=0; i<prCount; i++){
    let p = pParticles[i];
    let t1 = pts1[i % pts1.length], t2 = pts2[i % pts2.length];
    let tx = lerp(t1.x, t2.x, tProg), ty = lerp(t1.y, t2.y, tProg);

    if(cStage === 0) {
      let t = ((i / prCount) + Date.now()*0.0005) * Math.PI * 2;
      let scale = Math.min(pW, pH) * 0.3;
      tx = pW/2 + (scale * Math.cos(t)) / (1 + Math.sin(t)*Math.sin(t));
      ty = pH/2 + (scale * Math.sin(t) * Math.cos(t)) / (1 + Math.sin(t)*Math.sin(t));
    }

    p.x += (tx - p.x) * 0.1; p.y += (ty - p.y) * 0.1;

    pCtx.beginPath(); pCtx.arc(p.x, p.y, 2, 0, Math.PI*2);
    pCtx.fillStyle = p.c; pCtx.fill();
  }
  requestAnimationFrame(drawPortal);
}
drawPortal();
